    ('<span><b data-u="d">--</b>jours</span>', '<span><b data-u="d">--</b>days</span>'),
    ('<span><b data-u="h">--</b>heures</span>', '<span><b data-u="h">--</b>hours</span>'),
    ('<span><b data-u="s">--</b>sec</span>', '<span><b data-u="s">--</b>sec</span>'),
    ("<li><b>Tranche</b> les cubes lancés en l’air d’un glissement de doigt&nbsp;: bleu 1 dégât, vert 5, violet 20, jaune 50.</li>", "<li><b>Slice</b> the cubes thrown in the air with a swipe: blue 1 damage, green 5, purple 20, yellow 50.</li>"),
    ("<li><b>Évite les rouges</b>&nbsp;: ce sont des bombes, elles t’enlèvent 10 dégâts.</li>", "<li><b>Avoid the red ones</b>: they’re bombs and take away 10 damage.</li>"),
    ("<li><b>Plusieurs cubes d’un seul geste</b>&nbsp;: les dégâts sont multipliés, jusqu’à x7.</li>", "<li><b>Several cubes in one swipe</b>: damage is multiplied, up to x7.</li>"),
    ("<li><b>Le cube blanc</b>&nbsp;: tranche-le et tout se fige 5 secondes, chaque coup fait plus mal.</li>", "<li><b>The white cube</b>: slice it and everything freezes for 5 seconds, every hit hurts more.</li>"),
    ("<li><b>Les récompenses</b> dépendent de ta place au classement des dégâts&nbsp;: jusqu’à 1&nbsp;000 gems et un titre unique pour le 1er, même si le boss survit.</li>", "<li><b>Rewards</b> depend on your place in the damage ranking: up to 1,000 gems and a unique title for 1st place, even if the boss survives.</li>"),
    ('aria-label="Mini-jeu : entraînement contre le Cadeau Piégé"', 'aria-label="Mini-game: training against the Trapped Gift"'),
    ("<span>Dégâts <b class=\"slice-dmg\">0</b></span>", "<span>Damage <b class=\"slice-dmg\">0</b></span>"),
    ("<span>Temps <b class=\"slice-time\">20</b></span>", "<span>Time <b class=\"slice-time\">20</b></span>"),
    ("<span>Record <b class=\"slice-best\">0</b></span>", "<span>Best <b class=\"slice-best\">0</b></span>"),
    ('<p class="slice-hp-text">1&nbsp;000 / 1&nbsp;000 PV</p>', '<p class="slice-hp-text">1,000 / 1,000 HP</p>'),
    ('<p class="mg-title slice-title">Entraîne-toi&nbsp;!</p>', '<p class="mg-title slice-title">Train now!</p>'),
    ('<p class="mg-text slice-text">Un Cadeau Piégé d’entraînement, 1&nbsp;000&nbsp;PV et 20 secondes. Glisse le doigt sur les cubes pour les trancher (à la souris&nbsp;: clique et glisse), et évite les rouges.</p>',
     '<p class="mg-text slice-text">A training Trapped Gift, 1,000 HP and 20 seconds. Swipe across the cubes to slice them (with a mouse: click and drag), and avoid the red ones.</p>'),
